def interpolate_percentile(
    signal_name: str,
    turn: int,
    percentile: int,
) -> float:
    """
    Interpolate a percentile value for a signal at any turn.

    Args:
        signal_name: Name of the signal (e.g., "techs_known")
        turn: Turn number to get percentile for
        percentile: Percentile to get (10, 25, 50, 75, or 90)

    Returns:
        Interpolated percentile value
    """
    if signal_name not in SIGNAL_STATS:
        raise ValueError(f"Unknown signal: {signal_name}")

    stats = SIGNAL_STATS[signal_name]
    turns = sorted(stats.keys())

    pkey = f"p{percentile}"

    # Exact match
    if turn in stats:
        return stats[turn][pkey]

    # Find surrounding turns for interpolation
    lower_turn = max(t for t in turns if t <= turn) if any(t <= turn for t in turns) else turns[0]
    upper_turn = min(t for t in turns if t >= turn) if any(t >= turn for t in turns) else turns[-1]

    if lower_turn == upper_turn:
        return stats[lower_turn][pkey]

    # Linear interpolation
    lower_val = stats[lower_turn][pkey]
    upper_val = stats[upper_turn][pkey]

    ratio = (turn - lower_turn) / (upper_turn - lower_turn)
    return lower_val + ratio * (upper_val - lower_val)


def get_threshold_for_rate(
    signal_name: str,
    resolution_turn: int,
    target_rate: float = 0.4,
    current_value: float | None = None,
) -> float:
    """
    Get a threshold that achieves approximately the target True rate.

    For a question "Will signal >= threshold by resolution_turn?",
    this returns a threshold such that ~target_rate of games will answer True.

    Args:
        signal_name: Name of the signal (e.g., "techs_known", "population")
        resolution_turn: Turn at which the question is resolved
        target_rate: Target fraction of True answers (default 0.4 = 40%)
        current_value: Optional current value to ensure threshold is above it

    Returns:
        Threshold value

    Example:
        # For 40% True rate: pick the 60th percentile
        # (60% will be below threshold, 40% at or above)
        threshold = get_threshold_for_rate("techs_known", 125, target_rate=0.4)
        # Returns ~35 (60th percentile of tech count at turn 125)
    """
    # Convert target rate to percentile
    # If we want X% True, we need the (100-X) percentile
    # e.g., 40% True -> 60th percentile
    target_percentile = int((1 - target_rate) * 100)

    # We only have p10, p25, p50, p75, p90 - interpolate between them
    available = [10, 25, 50, 75, 90]

    if target_percentile in available:
        threshold = interpolate_percentile(signal_name, resolution_turn, target_percentile)
    else:
        # Interpolate between adjacent percentiles
        lower_p = max(p for p in available if p <= target_percentile)
        upper_p = min(p for p in available if p >= target_percentile)

        if lower_p == upper_p:
            threshold = interpolate_percentile(signal_name, resolution_turn, lower_p)
        else:
            lower_val = interpolate_percentile(signal_name, resolution_turn, lower_p)
            upper_val = interpolate_percentile(signal_name, resolution_turn, upper_p)
            ratio = (target_percentile - lower_p) / (upper_p - lower_p)
            threshold = lower_val + ratio * (upper_val - lower_val)

    # Ensure threshold is above current value if provided
    if current_value is not None and threshold <= current_value:
        # Pick a threshold slightly above current value
        # Use the 75th percentile as fallback (harder question)
        threshold = max(
            current_value + 1,
            interpolate_percentile(signal_name, resolution_turn, 75)
        )

    # Round to clean integer for most signals
    return round(threshold)


def get_growth_threshold_for_rate(
    signal_name: str,
    snapshot_turn: int,
    resolution_turn: int,
    target_rate: float = 0.4,
) -> float:
    """
    Get a growth threshold (change from snapshot to resolution) for target rate.

    For questions like "Will territory increase by X from turn 50 to turn 125?"

    Args:
        signal_name: Name of the signal
        snapshot_turn: Starting turn
        resolution_turn: Ending turn
        target_rate: Target True rate

    Returns:
        Growth threshold value
    """
    if signal_name not in GROWTH_STATS:
        raise ValueError(f"No growth stats for signal: {signal_name}")

    # Find matching window
    window_key = f"{snapshot_turn}_to_{resolution_turn}"

    # If exact match not found, find closest
    if window_key not in GROWTH_STATS[signal_name]:
        # Try standard windows based on resolution turn
        if resolution_turn <= 70:
            window_key = "50_to_70"
        elif resolution_turn <= 125:
            window_key = "50_to_125"
        else:
            window_key = "50_to_200"

    if window_key not in GROWTH_STATS[signal_name]:
        raise ValueError(f"No growth stats for window: {window_key}")

    stats = GROWTH_STATS[signal_name][window_key]

    # Convert target rate to percentile
    target_percentile = int((1 - target_rate) * 100)

    # Interpolate
    available = [10, 25, 50, 75, 90]
    lower_p = max(p for p in available if p <= target_percentile)
    upper_p = min(p for p in available if p >= target_percentile)

    lower_val = stats[f"p{lower_p}"]
    upper_val = stats[f"p{upper_p}"]

    if lower_p == upper_p:
        threshold = lower_val
    else:
        ratio = (target_percentile - lower_p) / (upper_p - lower_p)
        threshold = lower_val + ratio * (upper_val - lower_val)

    return round(threshold)


def get_event_probability(event_type: str, horizon: str) -> float:
    """
    Get the probability of an event occurring within a horizon.

    Args:
        event_type: Type of event (e.g., "city_founded", "city_conquered")
        horizon: Time horizon ("H1", "H2", or "H3")

    Returns:
        Probability (0.0 to 1.0)
    """
    if event_type not in EVENT_PROBABILITIES:
        return 0.5  # Default if unknown

    return EVENT_PROBABILITIES[event_type].get(horizon, 0.5)


def get_rank_1_probability(turn: int) -> float:
    """
    Get the probability of achieving rank 1 (highest score) at a turn.

    Args:
        turn: Turn number

    Returns:
        Probability (0.0 to 1.0)
    """
    if turn in RANK_1_PROBABILITY:
        return RANK_1_PROBABILITY[turn]

    # Interpolate
    turns = sorted(RANK_1_PROBABILITY.keys())
    if turn < turns[0]:
        return RANK_1_PROBABILITY[turns[0]]
    if turn > turns[-1]:
        return RANK_1_PROBABILITY[turns[-1]]

    lower_t = max(t for t in turns if t <= turn)
    upper_t = min(t for t in turns if t >= turn)

    if lower_t == upper_t:
        return RANK_1_PROBABILITY[lower_t]

    ratio = (turn - lower_t) / (upper_t - lower_t)
    return RANK_1_PROBABILITY[lower_t] + ratio * (RANK_1_PROBABILITY[upper_t] - RANK_1_PROBABILITY[lower_t])


# Signal name mappings (generator uses different names than time series)
SIGNAL_NAME_MAP = {
    "techs_known": "techs_known",
    "population": "population",
    "territory_size": "territory_size",
    "treasury": "treasury",
    "cities_count": "cities_count",
    # Aliases used by templates
    "score": "population",  # Use population as proxy for score
}


def get_canonical_signal_name(signal_name: str) -> str:
    """Get the canonical signal name for statistics lookup."""
    return SIGNAL_NAME_MAP.get(signal_name, signal_name)
